# ==============================================================================# 098_CONTRACT_ENGINE.py## IOTEC CONTRACT ENGINE## Missão:# Criar contratos somente após negociação vencedora.# ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class ContractEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_contracts(            id INTEGER PRIMARY KEY AUTOINCREMENT,            contract_uuid TEXT UNIQUE,            proposal_uuid TEXT,            opportunity_uuid TEXT,            company_uuid TEXT,            contract_number TEXT,            contract_value REAL,            currency TEXT,            status TEXT,            signed_at TEXT,            valid_from TEXT,            valid_until TEXT,            created_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def create_contract(self, proposal_uuid):        proposal=self.conn.execute("""            SELECT *            FROM commercial_proposals            WHERE proposal_uuid=?            LIMIT 1        """,(proposal_uuid,)).fetchone()        if proposal is None:            raise RuntimeError("Proposta não encontrada.")        negotiation=self.conn.execute("""            SELECT *            FROM commercial_negotiations            WHERE proposal_uuid=?              AND event_type='NEGOTIATION_WON'            LIMIT 1        """,(proposal_uuid,)).fetchone()        if negotiation is None:            raise RuntimeError(                "Contrato não permitido. "                "Não existe evento NEGOTIATION_WON."            )        payload={            "contract_uuid":str(uuid.uuid4()),            "proposal_uuid":proposal["proposal_uuid"],            "opportunity_uuid":proposal["opportunity_uuid"],            "company_uuid":proposal["company_uuid"],            "contract_number":"CTR-"+datetime.utcnow().strftime("%Y%m%d%H%M%S"),            "contract_value":proposal["estimated_value"],            "currency":"BRL",            "status":"DRAFT",            "signed_at":None,            "valid_from":None,            "valid_until":None,            "created_at":datetime.utcnow().isoformat(),            "metadata":{                "origin":"098_CONTRACT_ENGINE"            }        }        assinatura=self._sha(payload)        self.conn.execute("""        INSERT INTO commercial_contracts(            contract_uuid,            proposal_uuid,            opportunity_uuid,            company_uuid,            contract_number,            contract_value,            currency,            status,            signed_at,            valid_from,            valid_until,            created_at,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["contract_uuid"],            payload["proposal_uuid"],            payload["opportunity_uuid"],            payload["company_uuid"],            payload["contract_number"],            payload["contract_value"],            payload["currency"],            payload["status"],            payload["signed_at"],            payload["valid_from"],            payload["valid_until"],            payload["created_at"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"]=assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    conn=sqlite3.connect(DB)    conn.row_factory=sqlite3.Row    proposta=conn.execute("""        SELECT proposal_uuid        FROM commercial_proposals        LIMIT 1    """).fetchone()    if proposta is None:        raise RuntimeError("Nenhuma proposta encontrada.")    engine=ContractEngine()    resultado=engine.create_contract(        proposta["proposal_uuid"]    )    print("="*80)    print("CONTRACT ENGINE")    print("="*80)    for k,v in resultado.items():        print(f"{k:20}: {v}")    print("="*80)